-- 2408 🏋️ Exercises from the book "dutch-academy-football-coaching-u14-15-functional-training-tactical-practices-fr" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'dutch-academy-football-coaching-u14-15-functional-training-tactical-practices-fr');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Full back build-up functional pattern', 'passing_opposed', 'passive', 'in_possession', 29, 30, 'Building Up Play with the Full Back (Step 1): Functional Training', NULL, 'Build up from the back through the full back, who must beat a pressing defender.', 'Quarter of a full pitch near the penalty area; centre back at edge of the box, right back wide by a cone, midfielder further up near a cone gate and goal; one or two defenders; at least 2 players per position.', 'CB rolls the ball out to open up, then passes in front of the right back as a defender steps up to press. The right back either plays straight into the midfielder or beats the defender inside or outside first, then passes to the midfielder, who controls and dribbles through the gate and back to the start. Players rotate CB to FB to midfielder.', NULL, 'Defender passive; vary speed and distance of the defender''s approach; demonstrate moves and have the full back use a set move (e.g. feint and cut) inside or outside; finally a fully active defender who can score in one of two goals defended by the CB and midfielder.', 'Vision over pure technique - when to pass, when to go alone. CB: firm accurate pass into the full back''s path. FB: get off the line, check away from the cone, receive on the move. Midfielder: stay high, receive on the move.', 'at least 2 per position plus 1-2 defenders', 7, NULL, '1/4 of a full pitch', NULL, NULL, NULL, true, false, true, 'U14-U15', 10),
  ('Full back build-up 2v1 then 2v2 to goal', 'phase_of_play', 'opposed', 'in_possession', 31, 31, 'Building Up Play with the Full Back (Step 2): Small Sided Game (2 v 1 / 2 v 2)', NULL, 'Competitive 2v1 / 2v2 build-up from the back through the full back.', 'Same set-up as Step 1 but with two full size goals and goalkeepers; CB starts, full back and midfielder against one live defender.', 'CB passes to the full back, who combines with the midfielder against the defender to score a 2v1 goal. If the defender wins it he attacks the opposite goal. Players rotate CB to FB to midfielder after each phase.', 'Defender fully live from the start; turnovers can be scored at the other end.', 'Add a second defender behind the midfielder so it becomes 2v2.', 'Keep running if you can; pass forward if the defender closes; fake one way and go the other; the target man can turn and shoot or set it back.', '3 attackers v 1-2 defenders + 2 GKs', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U14-U15', 20),
  ('Full back build-up 3v3 with keepers', 'small_sided_game', 'opposed', 'in_possession', 32, 32, 'Building Up Play with the Full Back (Step 3): Small Sided Game (3 v 3 + GKs)', NULL, 'Build up through the full back in a 3v3 where every attacker has a direct marker.', 'Two goals with keepers; orange CB, full back and midfielder each matched by a blue defender (one closes the CB, one the full back, one behind the midfielder).', 'The orange keeper starts by passing to the CB; the oranges build through the full back and try to combine or dribble past their opponents to score 3v3. Blues press and counter to the other goal if they win it. Restart from the orange keeper.', 'Restart with the orange goalkeeper after each attack or ball out.', NULL, 'Build only through the full back; beat your man by passing as well as dribbling.', '3v3 + 2 GKs', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U14-U15', 30),
  ('6+GK v 4 build-up through full backs', 'phase_of_play', 'overload', 'in_possession', 33, 33, 'Building Up Play with the Full Back (Step 4): 6 (+GK) v 4 Positional Play', NULL, 'Build up from the back through the full backs against a front-four press.', 'Half pitch; oranges: GK, 1 CB, 2 full backs, 3 central midfielders; blues: striker, 2 wingers, 2 central midfielders (book lists 4 v 6 positions). Two small goals on the halfway line, big goal with GK at the end.', 'Oranges build from the keeper, mainly through the full backs, and score in one of the small halfway goals. Blues press, win the ball and finish past the keeper. Restart with the orange keeper.', 'No long balls - build up from the back.', NULL, 'Play through the full backs; beat opponents by dribbling as well as passing; switch play full back to full back to use the whole width; coach decision making.', '6 (+GK) v 4', 11, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 40),
  ('Four 1v1 moves in channels', 'technical', 'unopposed', 'in_possession', 37, 38, 'Moves to Beat a Defender (1 v 1) with the Opponent in Front', NULL, 'Master four moves to beat a defender who is directly in front.', 'Four channels of about 2 x 6 yards, a cone in the middle of each, 4 pairs working at once, each player with a ball.', 'Player dribbles at the cone, performs the set move (Matthews, scissors, double scissors, side step) to go past it, then carries on to the end; partner comes back the opposite way.', NULL, 'One ball per pair and no cone: partners take turns as a passive defender and the attacker uses the set move at the right moment.', 'Demonstrate first; demand more pace and explosive exit, more distance, combine two moves; go different directions to avoid clashes; perform with conviction; drop the shoulder and bend the knees.', '4 pairs', 8, 8, '4 channels approx 2 x 6 yards', 5.5, 1.8, NULL, false, false, true, 'U14-U15', 50),
  ('Continuous 1v1 moves at different angles', 'one_v_one', 'passive', 'in_possession', 39, 39, 'Moves to Beat a Defender (1 v 1) at Different Angles in a Continuous Practice', NULL, 'Beat defenders with moves from different approach angles.', 'Four channels about 5 x 15 yards; 4 attackers with balls facing 4 defenders, 3 extra defenders beside the attackers, rest queue at the start.', 'Attacker plays a one-two with a defender, receives, then takes him on with a move and dribbles past; then crosses diagonally to confront the next defender who steps forward. Continuous through the channels until the last defender, then back to the start.', 'Defenders passive - press forward then run back so the tempo stays high.', 'Increase defender resistance gradually to make it competitive.', 'Approach from a new angle each time; keep the ball close then strike with the planned move; include a feint before changing direction; once you commit, go at full pace.', '4 attackers + 7 defenders + queue', 11, NULL, '4 channels approx 5 x 15 yards', 13.7, 4.6, NULL, false, false, true, 'U14-U15', 60),
  ('Pass and move then explosive 1v1', 'one_v_one', 'opposed', 'in_possession', 40, 40, 'Explosive Power/Speed to Beat a Defender in a ''Pass and Move'' Practice', NULL, 'Inside-foot passing combined with an explosive 1v1 to beat a defender.', '10 x 10 yard square with an extra end zone; max 6 players at positions A, B, C and D (D on the edge of the end zone).', 'A passes diagonally to B, B to C, C one-twos with A then sprints round behind B to receive a weighted pass from A. D steps out as C receives; C beats D 1v1 and dribbles into the end zone and stops the ball. Rotate A to B to C to D to A.', 'C must stop the ball under control inside the end zone.', 'Change area size by age/level; use a line to dribble over instead of a zone.', NULL, 'max 6', 4, 6, '10 x 10 yards + end zone', 9.1, 9.1, NULL, false, false, true, 'U14-U15', 70),
  ('Switch to winger, beat mannequin, combine', 'combination', 'unopposed', 'in_possession', 41, 41, 'Receive, Dribble & Beat a Defender on the Flank in a Passing Combination Practice', NULL, 'Long switching pass, winger''s first touch and beating a defender 1v1 on the flank.', 'Attacking half; two central midfielders (6, 8), a No.10, two wingers (7, 11) and a striker (9); six mannequins as defenders on the flanks.', '6 passes to 8, who switches long to the left winger; winger controls and dribbles at the mannequins using a move. Striker checks away and receives from the winger, the 10 gets the next pass and returns it to the start. Then repeat on the right with 6 switching to 7.', NULL, 'Rotate positions each sequence; resting winger acts as a passive defender; add a GK and have the winger cross for the 10 and striker to finish.', NULL, '6 plus extra wingers', 6, 8, 'Attacking half', NULL, NULL, NULL, false, false, true, 'U14-U15', 80),
  ('Penalty-area combination into 1v1 box', 'one_v_one', 'opposed', 'in_possession', 42, 42, 'Passing, Receiving, 1 v 1 and Finishing in and Around the Penalty Area', NULL, 'Quick passing around the box, then a 1v1 duel and finish on goal.', '8 x 8 yard zone at the top of the box with one defender inside; goalkeeper; 6 attackers, 5 at positions A-E plus one waiting on the other side.', 'A passes to C while B steps out to pressure; C turns away from B and passes to D in the centre, who plays E. E dribbles into the 8 x 8 zone, beats the defender 1v1 and shoots.', 'Defender fully live and stays in until he wins the ball; then he goes to A and the loser defends. Alternate sides.', 'Bigger defender zone for harder, smaller for easier; A plays a one-two with C under B''s pressure before passing to D.', NULL, '6 attackers + 1 defender + GK', 8, 8, '8 x 8 yard box at the top of the penalty area', 7.3, 7.3, NULL, true, true, true, 'U14-U15', 90),
  ('Central 1v1 to goal from long pass', 'one_v_one', 'opposed', 'in_possession', 43, 43, 'Winning a 1 v 1 Duel in the Centre and Finishing on Goal', NULL, 'Attack a defender face-on in a central 1v1 and finish.', 'Half pitch; big goal and GK at one end with 2 defenders either side; 2 small goals on the halfway line; 4 attackers spread across the halfway line.', 'A defender plays long to an orange winger, who passes into one of two central team-mates; the defender closes and the receiver takes him on 1v1 to score. If the defender wins it he scores in a small goal or plays back to the GK.', 'Alternate the first pass left/right; defenders take turns, attackers rotate. Keep score in mini-games of 4 balls.', NULL, 'Call for the ball with conviction; take the first touch forward and go for goal early; call for it everywhere and solve bad passes creatively.', '4 attackers + 4 defenders + GK', 9, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 100),
  ('Wide 1v1 to goal, defender''s choice', 'one_v_one', 'opposed', 'in_possession', 44, 44, 'Winning a 1 v 1 Duel on the Side and Finishing on Goal', NULL, 'Win a 1v1 from the wing against a defender in front and finish.', 'As the previous practice (half pitch, big goal + GK, 2 small halfway goals) with a defender each side of the goal and a third on the edge of the box.', 'The serving defender either passes straight to a winger on halfway and runs out to defend 1v1, or passes to the defender on the edge of the box, who plays an orange attacker who sets it wide; the winger then takes on the edge-of-box defender 1v1 and finishes.', 'In option 1 the edge-of-box defender stays out. Defenders who win it score in a small goal or play back to the GK.', NULL, NULL, '4 attackers + 3 defenders + GK', 8, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 110),
  ('4v4 dribble into end zones', 'small_sided_game', 'opposed', 'in_possession', 47, 47, '4 v 4 Small Sided Game (1): Individual Play with Dribbling End Zones', NULL, 'Dribbling and moves to beat defenders in 1v1 situations.', '20 x 35 yard area with a 5 yard end zone at each end (20 x 25 middle zone); 4v4.', 'A player starts by passing from the end zone and moves into the middle; teams play 4v4 and score by dribbling into the opposite end zone, using individual play to get past opponents.', 'Restart with a pass from an end zone after ball out; after a goal the scorers drop back and the conceding team restarts. Short intervals with rest.', '3v3 or 5v5; lines to dribble over instead of zones; time limit to score or lose possession.', NULL, '4v4', 8, 8, '20 x 35 yards', 32.0, 18.3, NULL, false, false, true, 'U14-U15', 120),
  ('4v4 shooting with two big goals', 'small_sided_game', 'opposed', 'in_possession', 48, 48, '4 v 4 Small Sided Game (2): Shooting and Finishing with 2 Goals + GKs', NULL, 'Shooting and finishing under time and space pressure.', '20 x 35 yards, no end zones, two full size goals with goalkeepers; 4v4.', 'A keeper starts play and the teams play 4v4 to score in the big goals, shooting often in the tight space.', 'Restart from the keeper; after a goal the scorers drop back and the conceding team restarts. Short intervals with rest.', '3v3 or 5v5; time limit to score or lose possession.', NULL, '4v4 + 2 GKs', 10, 10, '20 x 35 yards', 32.0, 18.3, NULL, true, true, true, 'U14-U15', 130),
  ('4v4 five passes then four mini goals', 'small_sided_game', 'opposed', 'in_possession', 49, 49, '4 v 4 Small Sided Game (3): Passing and Possession with 4 Goals', NULL, 'Passing, receiving, movement and combination play in a small sided game.', '40 x 25 yard area (40 wide on the goal sides) with two mini goals on each end line; 4v4; balls at the end lines.', 'A player starts from the end line with a pass; teams play directional 4v4 and attack either of the two mini goals at the opposite end.', '5 consecutive passes required before a team may score. Restart from the end line; after a goal the scorers drop back. Short intervals.', '3v3 or 5v5; time limit to score or lose possession.', NULL, '4v4', 8, 8, '40 x 25 yards', 22.9, 36.6, NULL, true, false, true, 'U14-U15', 140),
  ('Inside-foot keep-ball in 5v2 zones', 'rondo', 'overload', 'in_possession', 79, 80, 'Receive and Pass with the Inside of the Foot in 5 v 2 Zones', NULL, 'Clean inside-foot control and passing so the build-up does not lose the ball to technical errors.', 'Three boxes about 15-20 x 25-30 yards, no more than 5 yards apart; one box stands alone with a goal and keeper beyond it, the other two sit side by side. Two balls in play at once.', 'In the goal box 5 oranges keep the ball from 2 blues, who score in the goal if they win it. In the paired boxes 5 blues keep it from 2 oranges; if the pair wins it they try to pass across to their 5 team-mates in the other box, while the side that lost it presses at once to block that switch.', '10 passes in a row = 1 point. Ball out: coach serves a new ball and play restarts. Encourage fewer touches for attackers.', 'Two teams of 7 in two sections, 75-second rounds, most consecutive passes wins a point; or play 5v3 / 3v3+2 neutrals per box.', 'Inside of the foot not toe; meet bouncing balls on top; both feet; first touch out in front towards the next pass; strike through the middle; firm ankle; weight the pass to the distance and pressure; pass to the correct foot; be on your toes, half-open, ready to receive. Defending pair close angles together.', '5v2 per box, two teams of 7 (14 + GK)', 14, 15, '15-20 x 25-30 yards per zone', 27.4, 18.3, NULL, true, true, false, 'U14-U15', 150),
  ('4(+2) v 4(+2) receive and pass quickly', 'possession', 'opposed', 'in_possession', 81, 82, 'Positioning and Movement to Receive and Pass Quickly in a 4 (+2) v 4 (+2) Possession Game', NULL, 'Movement off the ball to create space, receiving on the half-turn and quick accurate passing.', '40 x 40 yard square, 4v4 inside, each team has 2 more players on the outside lines. Coach with balls on the side.', 'Coach feeds one team, which keeps the ball 4(+2) v 4 using its outside players. Blues win it and try to string their own passes with their outside pair.', 'Outside players on 1-2 touches; option: outside player who receives dribbles in and the passer swaps out; coach decides if wall passes back to the passer or between outside players are allowed. Set number of passes = 1 point.', 'Change area size or numbers; limit everyone to 2-3 touches. Variations: only 2 neutral outside players on opposite sides for the team in possession, or no outside players and 1-2 neutrals inside.', 'Touch it so you can play it on, never under your feet; control on the move and avoid duels; make space for the ball; look for the deepest player and play to his correct side; inside foot through the middle; move left/right to open the line; move away to create space for others; keep the space big.', '4v4 + 2 outside per team (12)', 12, 12, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, 'U14-U15', 160),
  ('Three-zone end-to-end forward-pass game', 'positional_game', 'opposed', 'in_possession', 83, 83, 'Playing Forward Passes in a 3 Zone End to End Possession Game', NULL, 'Playing forward through a middle zone from one end player to the other.', '15 x 30 yard area with two thin end zones (15 x 3 yards) holding 1 orange and 1 blue each; 4v4 in the middle zone; everyone stays in their zone.', 'Play starts with a centre back in an end zone. The team in possession works the ball through the middle to its player in the far end zone for a point, then keeps it and plays back the other way. Defenders who win it do the same towards their own end players; end-zone defenders are fully active.', 'Free play first, then 1-2 touches. First to 5 points wins.', 'Restrict to 1 or 2 touches.', 'Hold formation roles (e.g. diamond midfield); everything prepares the forward pass; play forward the moment the defender steps to the ball; middle players check away before showing.', '6v6 (4v4 middle + 1v1 in each end zone)', 12, 12, '15 x 30 yards', 27.4, 13.7, NULL, false, false, true, 'U14-U15', 170),
  ('Positional 6v3 forward passing', 'rondo', 'overload', 'in_possession', 84, 84, 'Passing Forward in a Positional 6 v 3 Possession Game', NULL, 'Moving the ball forward from end to end while holding positional roles.', 'Rectangle around the centre circle. Oranges: centre back, 2 full backs (or wingers) and a striker start on the outside lines, 2 central midfielders inside; 3 blue central midfielders inside.', 'Oranges circulate 6v3, aiming to play from one end (CB) to the other (striker) and then back the opposite way. Outside players may step in when involved, e.g. CB carrying in to pass forward.', 'Start free, progress to 1-2 touches. Coach times how long the 3 take to win the ball; the trio tries to beat their time.', 'Restrict touches to 1 or 2.', 'Forward pass is the focus, mix short and long; sideways or back passes only set it up; play forward when the defender presses; reach the far player through good positioning.', '6v3', 9, 9, NULL, NULL, NULL, NULL, false, false, true, 'U14-U15', 180),
  ('4v4 end to end with keeper end zones', 'positional_game', 'opposed', 'in_possession', 85, 85, '4 v 4 (+2) End to End Possession Game with Goalkeeper End Zones', NULL, 'Technique and vision in the build-up, playing forward from one keeper to the other.', 'Main zone with 4v4 and an end zone at each end holding one goalkeeper (neutral).', 'A keeper passes to one team (e.g. the CB). That team tries to reach the opposite keeper without the other side touching the ball for a point, then keeps the ball and goes back the other way. Defenders who win it pass to a keeper and play towards the far one.', 'Defenders may only enter an end zone once the keeper has the ball. Start free, then 1-2 touches.', 'Limit to 1 or 2 touches.', 'Fixed roles: 1 CB (or CM), 2 full backs/wingers, 1 forward; focus on the forward pass end to end, mixing short and long; side/back passes only to set up the forward pass.', '4v4 + 2 GKs', 10, 10, NULL, NULL, NULL, NULL, false, true, true, 'U14-U15', 190),
  ('Numbered passing sequence 7v7 middle third', 'possession', 'opposed', 'in_possession', 86, 86, 'Receiving in Space and Passing in Midfield (7 v 7 in the Middle Third)', NULL, 'Midfield qualities: keeping the ball, creating space, receiving and beating a man with a pass or dribble.', 'Middle third of a pitch; two teams of 7, each player numbered 1-7. Coach with balls on the side.', 'Coach serves a ball in. The team must pass in number order 1 to 7; when No.7 receives they score a point and restart with No.1.', 'Each player may only be tackled by the opponent wearing the same number (man-marking). Demanding physically - build in rests.', NULL, 'Get into the passer''s vision; don''t shrink the space; first touch sets up the next action; shield the ball; dribble towards the open side; never stand still - turn away at the right moment; beat your man with a cut, feint or pass-and-move; pass only when the receiver is free; think a step ahead (No.5 moves as No.3 receives).', '7v7', 14, 14, 'Middle third of the pitch', NULL, NULL, NULL, false, false, false, 'U14-U15', 200),
  ('5v4 centre back to striker, end line', 'phase_of_play', 'opposed', 'in_possession', 87, 88, 'Passing Direct from the Centre Back to the Striker when Building Up in a 5 v 4 Practice (1)', NULL, 'Playing forward passes from the back, straight into the striker.', '50 x 40 yards split into two sections, 2 small goals at one end and an end line at the other. Section 1: 4 orange defenders v 3 blue forwards; section 2: orange striker v 1 blue defender. Play starts from an orange between the small goals.', 'Oranges must get the ball into the striker in his zone; once he receives it, all zone limits drop and oranges try to dribble over the end line (the striker may go alone). Blues press to win it in either section and attack the small goals.', 'End line can only be crossed after a pass has reached the striker. Play to ball out or goal.', 'Blue front 3 press as a unit; lengthen the pass to the striker; striker v 2 blue CBs; full goal + keeper with 5v3 build-up; add players e.g. a central midfielder.', 'Touch to look and pass forward; ball never under your feet; eye contact with the striker; spot when his line opens; if shut, keep the pitch big and move it fast; full backs drop on time; hard, ground pass to his correct side; where is the triangle, where is the defender?', '5v4', 9, 9, '50 x 40 yards', 45.7, 36.6, NULL, true, false, true, 'U14-U15', 210),
  ('Three-zone build-up to striker then 2v1', 'phase_of_play', 'overload', 'in_possession', 89, 90, 'Passing Direct from the Centre Back to the Striker when Building Up in a 5 v 4 Practice (2)', NULL, 'Forward passing from the back into the striker, then exploiting a 2v1.', 'Full pitch, three zones the width of the penalty area. Low zone 20 yards long with 4 oranges v 2 blues; middle zone 1 orange striker with 1 blue defender behind; goal and keeper at the far end. Coach starts it in the low zone.', 'Oranges build 4v2 and pass into the forward. Then one low-zone player may join in the middle zone for a 2v1, and both are free to enter the box and score. Blues who win it dribble over the back line to score.', 'Only one player may move up from the low zone.', '3v1 in zone 1 (easier); shrink zone 1 (harder); 5v3 including keeper or 4v3 (harder); add defenders/forwards to the middle zone.', 'Position to receive and spin off the defender; tight touch then play to the striker at once; hard pass over the distance; eye contact; pass to his free side; follow your pass and use the 2v1.', '4v2 + 1v1 + GK', 9, 10, 'Full pitch, zones penalty-area width; first zone 20 yards long', NULL, NULL, NULL, true, true, true, 'U14-U15', 220),
  ('Keeper to CB to striker small-sided games', 'small_sided_game', 'opposed', 'in_possession', 91, 92, 'Passing Direct from the Centre Back to the Striker & Support Play in Small Sided Games', NULL, 'Recognise the striker''s run and play the direct pass from centre back with the right weight; also keeper technique in the build-up.', 'Two versions: 4v4 (+GKs) on 44 x 35 yards, or 5v5 (+GKs) on 60 x 50 yards with 2 wingers added. Full goals and keepers at both ends.', 'The keeper starts by passing to one of two centre backs, who aims to play straight into the striker; the team supports and scores. Defenders win it and score at the other end. Restart from a keeper after every goal or ball out.', NULL, '6v6 or 7v7 (+GKs).', 'Pitch big: striker checks away, wide players to the line, central pair split. CBs: touch to look forward, eye contact, firm ground pass to his correct side, find the triangle, other CB pushes on after the pass. Striker: time the call with the CB, check away, move off the defender''s back, don''t come short too early. Defenders: squeeze, play offside or press together.', '4v4 + 2 GKs or 5v5 + 2 GKs', 10, 12, '44 x 35 yards or 60 x 50 yards', 40.2, 32.0, NULL, true, true, true, 'U14-U15', 230),
  ('Keeper short or long distribution game', 'goalkeeping', 'opposed', 'in_possession', 93, 93, 'Goalkeeper''s Short & Long Distribution in a Dynamic Game', NULL, 'Keeper chooses the right short or long option; outfielders move to receive and build up.', 'Half a pitch, full goal at one end and 2 small goals on the halfway line. Oranges: keeper, back 4, No.10, 1 striker. Blues: 3 central midfielders, 2 wingers, 1 striker.', 'Coach passes to a centre back, who returns it to the keeper; a blue presses the keeper so one orange is left free. The keeper plays short or long and oranges build up to score in a small goal (keeper can also kick straight into one). Blues press, mark tight and score past the keeper if they win it.', 'Blue striker may press the keeper right after the back-pass''s first touch.', NULL, 'Keeper mixes short and long starts; decision first - empty goal or the free man.', '7v6 incl. GK', 13, 13, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 240),
  ('Keeper starts counter after defending a cross', 'transition', 'opposed', 'to_attack', 94, 94, 'Goalkeeper''s Short & Long Distribution after Defending a Set Piece', NULL, 'Counter-attack after defending a cross; keeper decides short or long to launch it.', 'Half pitch, full goal plus 2 small goals on halfway. 4v3 in the box (3 blue attackers v 4 orange defenders + keeper) and two 1v1s wide (orange winger v blue defender).', 'Coach or a blue crosses into the box; blues try to score, keeper and 4 oranges defend. A keeper catch or a defender''s clearance must start a fast counter to the wingers, the rest sprint up and attack the small goals. Blue markers stop the wingers turning, other blues recover.', NULL, NULL, 'Wingers tightly marked - keeper rolls it short; wingers free - keeper goes long.', '5v5 + GK', 11, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 250),
  ('6(+GK) v 4 build-up to midfield', 'phase_of_play', 'overload', 'in_possession', 95, 95, 'Building Up Play from the Goalkeeper through to Midfield in a 6 (+GK) v 4 Game', NULL, 'Building from the keeper through defenders and midfielders.', 'Half a pitch, full goal plus 2 small goals on halfway. Oranges: GK, 2 CBs, 2 full backs, 2 CMs (6 & 8). Blues: 3 forwards and a No.10.', 'Keeper starts; oranges create space, pick passing options and try to score in either small goal. Blues press to block forward passes and score past the keeper if they win it. Restart from the orange keeper.', 'Free play.', 'Oranges must score within a time limit; move small goals apart (easier) or together (harder).', 'Keeper finds the most advanced free player to speed up the build; keep creating space and finding the free man.', '6+GK v 4', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 260),
  ('Two-zone build-up, back four to forwards', 'phase_of_play', 'opposed', 'in_possession', 96, 96, 'Building Up Play from the Back Directly to the Forwards in a 2 Zone Game', NULL, 'Build-up from keeper to defenders and on to the forwards.', 'Area 10-15 yards longer than a full pitch, full goal one end, 3 small goals the other. Zone 1: orange keeper and back 4 v 3 blue forwards. Zone 2: 3 orange forwards v 3 blue defenders.', 'Keeper passes into zone 1; oranges pass or dribble into zone 2, after which zones drop and it becomes 7v6 attacking the small goals. Blues defend, win it and score in the full goal.', 'Blue forwards'' goal from winning it in zone 1 counts double. 10 starts from the orange keeper; most goals wins.', NULL, 'High tempo, everyone looking for the free man.', '7v6 incl. GK', 13, 13, 'Full pitch plus 10-15 yards', NULL, NULL, NULL, true, true, true, 'U14-U15', 270),
  ('Two-half SSG, pass or dribble forward', 'small_sided_game', 'opposed', 'in_possession', 97, 98, 'Moving the Ball Forward when Building Up Play from the Back in a SSG', NULL, 'Passing and dribbling forward in the build-up from the back.', 'Pitch split into halves with a full goal and keeper each end. Own half: 4 defenders (+GK) v 3 blue forwards; other half: 3 orange forwards v 4 blue defenders.', 'Orange keeper starts; the back line gets the ball to one of their 3 forwards in the other half. One orange defender can then join (by pass or dribble) to make 4v4 and attack the goal. If blues win it, half restrictions lift (time limit optional) and they attack the far goal. Restart from the other team''s keeper.', 'Only one defender may cross halfway.', 'Start 3 defenders v 3 forwards so the attack becomes 4v3; set up with defence, midfield and attack lines.', 'Stand wide with open body shape; CBs drop so full backs go high and wide; high tempo; talk and make eye contact with forwards; touch to look forward; play in when the line opens and the forward is ready, to his correct side; dribble forward if the striker is marked and space is ahead.', '8v8 incl. GKs', 16, 16, NULL, NULL, NULL, NULL, true, true, true, 'U14-U15', 280),
  ('8v8 five-zone full-back link-up', 'phase_of_play', 'opposed', 'in_possession', 99, 100, 'Connecting the Full Backs with the Front Line in an 8 v 8 Zonal Practice', NULL, 'Full backs building up with the 3 forwards.', 'Full pitch in 5 zones; middle zone 15-20 yards long. Zone 2: orange back 4 v 3 blue forwards; zone 4: 3 orange forwards v blue back 4 (keepers in zones 1 and 5).', 'Keeper plays into zone 2. Option 1: pass to a forward in zone 4, then a full back runs forward to take the lay-off in zone 3 and a 4v4 attack follows. Option 2: a forward drops into zone 3 to receive and a full back runs forward for another 4v4.', 'Blue defenders may enter zone 3 to defend. Offside applies.', 'Variation: 3v2 in zones 2 and 4 (1 CB + 2 full backs) to make the forward pass easier.', 'Full backs: don''t touch it too wide, be ready to play at once, eye contact with the striker, pass firm on the ground as he moves off, to feet only if he can turn, into space if he comes off the line diagonally; cut past a man who closes and drive into space for 2v1. Striker: call at the right moment, use arms to keep the defender off, stay high and show at an angle, run in behind, shield or one-touch, finish fast in a 2v1. Wingers: come short when marked, start deep and come inside, check away first, take it on the half-turn.', '8v8 incl. GKs', 16, 16, 'Full pitch, middle zone 15-20 yards long', NULL, NULL, NULL, true, true, true, 'U14-U15', 290),
  ('8v8 build from keeper, double goals', 'small_sided_game', 'opposed', 'in_possession', 101, 101, 'Building Up Play from the Back in an 8 v 8 Small Sided Game', NULL, 'Defenders and midfielders working together to build from the back.', 'Area between the two penalty boxes, full goals and keepers. Both teams in a 3-2-2 (1 CB, 2 full backs, 2 CMs, 2 wingers).', 'Always starts with the orange keeper; oranges build through combinations and movement to score. Blues win it and score. Restart from the orange keeper; after 5-10 attempts swap roles.', 'Goal from a build-up the opponents never touch counts double. Most goals after both sides'' attempts wins.', NULL, NULL, '8v8 incl. GKs', 16, 16, 'Between the two penalty areas', NULL, NULL, NULL, true, true, true, 'U14-U15', 300),
  ('Five-zone 1v1 and one-two warm-up', 'one_v_one', 'opposed', 'in_possession', 117, 118, NULL, NULL, 'Beating an opponent by dribbling or by a one-two with a support player.', 'Full pitch split into 5 marked zones of different sizes, each a different duel; zone 5 sits in front of a full goal with a keeper.', 'Pairs (attacker v defender) rotate through zones: plain 1v1 to the end line; 1v1 with two wide one-touch helpers for a wall pass; 1v1 with helpers at the ends; three pairs dueling at once in a wider zone; 1v1 (with or without helpers) then run in and finish against the keeper. Three duels per zone, then move on.', 'Outside helpers play one touch.', '2v2 version; small and multiple goals to score in.', 'Dribble at pace with the laces; drag the defender to one side; time the feint or pass (not too early or late); helpers not too far away; accelerate onto the return with a directional first touch.', 'Pairs plus outside helpers and a GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U14-U15', 310),
  ('Continuous 1v1 to small goals', 'one_v_one', 'opposed', 'in_possession', 119, 119, NULL, NULL, 'Getting past an opponent alone, with quick switching between attack and defence.', '15 x 20 yard box with a small goal at each end; 4 players, one pair inside, one waiting outside each side.', 'Attacker dribbles in, tries to beat the defender and score in the small goal; the defender tries to win it and score the other way. After a goal the defender takes a pass from his outside teammate and attacks while the old attacker defends. One-minute bouts, then the outside pair go in.', 'Beat the defender, intercept or score = 1 point each. Max 1 minute per bout.', 'Play 2v2; bigger goals with keepers.', NULL, '4 players (1v1 + 2 servers)', 4, 4, '15 x 20 yards', 13.7, 18.3, NULL, true, false, true, 'U14-U15', 320),
  ('Escape the defender and beat the keeper 1v1', 'finishing', 'opposed', 'in_possession', 120, 121, NULL, NULL, 'Better decisions and finishing in 1v1 against the goalkeeper under pressure.', 'Penalty-box width by half-pitch length, 7 x 7 yard square in the middle, full goals with keepers at both ends; two teams queue at opposite sides of the square.', 'Orange attacker calls for the ball, blue defender passes into the square and then defends. Attacker picks either goal, dribbles and tries to score past the keeper; if the defender wins it he attacks the other goal. After a goal the roles swap with a fresh ball from a teammate.', NULL, 'Change distances to goals and between the pair; start from other angles; defender starts behind and only defends fully after the first pass; for younger players stress feints and turns with smaller goals.', 'Shield the ball; keep pace and dribble round the keeper if there is space; close in: shoot high, nutmeg or chip after a fake; from further out shoot hard and low to the corner.', 'Two teams + 2 GKs', NULL, NULL, 'Penalty-area width x half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 330),
  ('Movement A: check to feet, then run in behind', 'one_v_one', 'opposed', 'in_possession', 122, 122, 'Movement With and Without the Ball (A)', NULL, 'Wingers and forwards learning when to show to feet and when to spin into space.', '25 x 35 yard area with two small cone gates (1 and 2) at the far end; coach with balls at the side; 2 blue defenders and up to 3 orange pairs (deep player + forward).', 'Coach passes in to the deep orange player. The tightly marked forward fakes coming short to lure the defender, then sprints in behind (inside or down the line); the pass is played into his run and he dribbles through a gate.', 'Dribble through a gate = 1 point; defender wins ball = 1 point.', 'Series continues with set-ups B to E.', 'Sell the short move, then explode away and call for it; pass must be timed and weighted; tight directional first touch towards a gate.', '2 blue defenders v up to 3 orange pairs + coach', NULL, NULL, '25 x 35 yards', 22.9, 32.0, NULL, false, false, true, 'U14-U15', 340),
  ('Movement B: receive, feint and dribble past', 'one_v_one', 'opposed', 'in_possession', 123, 123, 'Movement With and Without the Ball (B)', NULL, 'Receiving to feet when loosely marked and beating the defender with a feint.', 'Same 25 x 35 yard set-up with two cone gates as variation A.', 'Forward threatens to go deep but shows for the ball to feet, takes it forward at pace, keeps it close as the defender comes, then feints one way and goes the other before accelerating to the nearest gate.', 'Gate = 1 point.', 'Add a small goal for the defender to score in if he wins it (or dribble over a line).', 'Feint at the right moment; fake outside to go inside and vice versa; burst away after beating him.', 'Pairs v defender + coach', NULL, NULL, '25 x 35 yards', 22.9, 32.0, NULL, false, false, true, 'U14-U15', 350),
  ('Movement C: one-two with curved run', 'combination', 'opposed', 'in_possession', 124, 124, 'Movement With and Without the Ball (C)', NULL, 'Using a first-time layoff and curved run to get behind a defender who closes quickly.', 'Same 25 x 35 yard set-up with two cone gates.', 'Forward gets the first pass, lays it back first time to his teammate as the defender closes, then bends a run into the space behind; the teammate plays it first time into his path and he dribbles through a gate.', 'Gate = 1 point.', 'Add a small goal for the defender to counter into.', 'Lay-off must avoid the interception; go immediately after the pass; weight and timing of the return; directional first touch.', 'Pairs v defender + coach', NULL, NULL, '25 x 35 yards', 22.9, 32.0, NULL, false, false, true, 'U14-U15', 360),
  ('Movement D: drop deep and one-two', 'combination', 'opposed', 'in_possession', 125, 125, 'Movement With and Without the Ball (D)', NULL, 'Forward dropping off his marker, setting back and spinning in behind.', 'Same area; the orange forward and blue defender now start high up near the gates.', 'Deep orange player receives from the coach; forward drops, followed by his marker, gets the ball to feet and sets it back first time with the inside of the foot, then sprints in behind for a pass in front of him and dribbles through a gate.', 'Gate = 1 point.', 'Add a small goal for the defender.', 'One-touch inside-foot set; sprint away as soon as you pass; final ball in front of the runner; tight first touch to a gate.', 'Pairs v defender + coach', NULL, NULL, '25 x 35 yards', 22.9, 32.0, NULL, false, false, true, 'U14-U15', 370),
  ('Movement E: drop deep, turn and dribble', 'one_v_one', 'opposed', 'in_possession', 126, 126, 'Movement With and Without the Ball (E)', NULL, 'Forward dropping to receive and turning his marker in one move.', 'Same area, forward and defender starting high.', 'As D, but instead of setting back the forward turns with the ball, beats his marker in one action (inside or outside depending on the defender) and dribbles through a gate.', 'Gate = 1 point.', 'Add a small goal for the defender.', 'Read where the defender is; turn and dribble at the same speed as the drop; everything at high pace.', 'Pairs v defender + coach', NULL, NULL, '25 x 35 yards', 22.9, 32.0, NULL, false, false, true, 'U14-U15', 380),
  ('Back to goal: hold, turn and finish 1v1', 'finishing', 'opposed', 'in_possession', 127, 128, NULL, NULL, 'Forwards receiving with their back to goal, holding off a marker, turning and finishing.', 'Penalty-box width by half-pitch length; full goal with keeper, two cone gates at the sides and two small goals on halfway; pairs wait at the edge of the box.', 'Orange attacker calls for a pass from a teammate with a blue defender tight behind him; he controls, makes space, turns and shoots. Defender can intercept or hold him up; on winning it he dribbles through a side gate or scores in a small goal. Attacker can ask for a new ball after a goal or out of play. 45-60 seconds per pair.', 'Defender: side gate = 1 point, small goal = 2 points.', '2v2 for 60-75 seconds; no goals, dribble over the end line; two small goals instead of goal and keeper.', 'Call and point where you want it; body between man and ball; keep the ball moving; use your arm to feel him and turn when he is too tight or too eager; shoot when the path is clear; both feet.', 'Pairs (1v1) + GK + servers', NULL, NULL, 'Penalty-area width x half pitch', NULL, NULL, 1.0, true, true, true, 'U14-U15', 390),
  ('Striker''s back to goal: 2v2 and 3v2', 'phase_of_play', 'opposed', 'in_possession', 129, 130, NULL, NULL, 'Striker decision-making when receiving with back to goal to create chances.', 'Penalty-box width by half-pitch length; full goal + keeper, two side cone gates, two small goals on halfway; 5 orange and 5 blue, 4 outfield + GK active at once.', 'Orange player at the centre cone passes into the striker marked from behind and joins the attack; a second defender leaves his cone once the first pass goes. Striker sets back, turns, or lays it into space wide and the pair try to score (2v2). Defenders win it: gate = 1, small goal = 2.', 'First defender must let the striker receive, then defends fully.', 'Variation: two orange wingers out wide, first pass from wide, second defender starts centrally = 3v2 attack.', 'Striker: set back first time and re-offer, shield, arm contact on the turning side, turn when the defender is wrongly placed, watch offside. Support: pass to his back foot, stay in his eye-line; in 3v2 one winger stays in line, the other runs ahead.', '2v2 / 3v2 + GK', NULL, NULL, 'Penalty-area width x half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 400),
  ('2(+2)v2 duel zone then finish', 'one_v_one', 'opposed', 'in_possession', 131, 131, NULL, NULL, 'Beating defenders with dribbles or one-twos with wall players.', 'Area twice the size of the penalty box split into 2 zones; zone 1 holds 2v2 with two outside players on each flank, zone 2 is in front of a full goal and keeper.', 'Orange pair beat the defenders in zone 1 by dribbling or using an outside player for a wall pass; once through, one attacker carries into zone 2 and tries to score past the keeper.', 'Getting through zone 1 = 1 point; defenders only defend in zone 1 and score a point by winning it.', NULL, 'Dribble one way to open the other; pass at the right distance; pass to the side player with the outside of the foot to keep speed and hide the one-two; play to his inner leg; reward creativity.', '2v2 + 2 outside + GK', NULL, NULL, 'Double penalty area', NULL, NULL, NULL, true, true, true, 'U14-U15', 410),
  ('Three-team overload transition game', 'transition', 'overload', 'to_attack', 132, 133, NULL, NULL, 'Converting a numerical advantage (3v2, then 3v3 counters) into goals.', 'Penalty-box width by half-pitch length with full goals and keepers at both ends; 3 teams of 3; third team waits outside.', 'Keeper plays to orange, who attack 3v2 against two blues while the third blue waits with a ball. When the attack ends, the third blue dribbles on and the blues counter 3v3. After that phase the outside yellow team start a fresh 3v2 against oranges or blues.', NULL, 'Start 2v1 and build to 3v2 and 4v3; time limit (e.g. score in 10 s); small goals, no keepers.', 'Attack: high speed, no unnecessary passes, open up for the overlap, time the pass to the overlapper, others follow for rebounds. Counter: drive into space if it is there, offer ahead, if pressed pass and sprint, accurate final ball, note where the keeper is.', '3 teams of 3 + 2 GKs', 11, 11, 'Penalty-area width x half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 420),
  ('3v3 duels around the box with a target', 'phase_of_play', 'opposed', 'in_possession', 134, 135, NULL, NULL, '1v1 play and combinations between forwards in and around the penalty area.', 'Third of a full pitch with a full goal and keeper; small goals at the halfway end; coach with balls in the middle; 3 orange forwards v 3 blue defenders.', 'Striker calls for the coach''s pass while marked and combines with the two wide players to score. After a goal, out of play or loss, the striker can call for another ball. 75-90 seconds then rest.', 'Attackers may pick a target player limited to 2 touches.', 'Defenders can score by passing back to the coach or into a small goal.', 'Aim to free a teammate 1v1; if double-marked set up a one-touch finish; keep moving away from the defender; time runs into the box (between keeper and defender, or pull back); vary pass or shoot; wingers offer short or run behind if tightly marked; threaten one way and go the other.', '3v3 + GK + coach', 7, 7, 'Third of a pitch', NULL, NULL, 1.5, true, true, true, 'U14-U15', 430),
  ('Flank attacks in a 6v4 (+GK) game', 'phase_of_play', 'overload', 'in_possession', 136, 136, NULL, NULL, 'Creating chances from wide areas in a positional practice.', 'Half pitch with two wide channels, one orange winger in each; orange 4,6,8,7,11,9 v blue GK,4,2,3,10; balls at halfway.', 'Orange centre back starts; team builds up and finds a winger in a side channel, who attacks and crosses for runners. After the winger''s first touch both teams may enter and leave the channels freely.', 'Winger''s first touch in the channel is free. Winning moment: blues start 1-0 up, 6 minutes; orange must score twice to win; 4 x 6 minutes.', NULL, 'High tempo with quick passing and movement; coordinated runs to near post, far post etc.', '6v4 + GK', 11, 11, 'Half pitch', NULL, NULL, 24.0, true, true, true, 'U14-U15', 440),
  ('Flank attacks into a final zone 6v6 (+GK)', 'phase_of_play', 'opposed', 'in_possession', 137, 137, NULL, NULL, 'Combination play in the opposition half and attacking from the flank with wingers.', 'Half pitch: full goal and keeper at one end, two small goals on halfway, final zone marked level with the edge of the box; orange CB 4, 6, 8, 7, 11, 9 v blue three central midfielders, two full backs, one centre back.', 'Orange CB starts; team plays out to a winger, who (or the 9) must dribble over the line into the final zone before finishing; then zone limits drop. Blues win it and score in a small goal.', 'Blue defenders may enter the final zone only once the winger dribbles in. Goal from a winger''s cross counts double.', 'Change the defending formation to make it easier or harder.', 'Create a 1v1 forward v defender; time the run in behind to attack the space.', '6v6 + GK', 13, 13, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 450),
  ('Keep the ball after a long goal kick, attack wide', 'small_sided_game', 'opposed', 'in_possession', 138, 138, NULL, NULL, 'Keeping possession after the keeper''s distribution and creating chances from the flank.', 'Full pitch with a marked main area; keeper outside it; orange CB 4, 6, 8, 10, 7, 11, 9 v blues in a 3-3; full goal + keeper at one end, small goal at the other.', 'Keeper either goes long to a winger with space or short to a central midfielder who switches it wide. Orange keep the ball, then attack on the flank to score; blues try to win it and score in the small goal. 10 repetitions from the keeper, most goals wins.', NULL, NULL, 'For a player strong in the air play it high; for a technical player pass into the space in front of him or to his body.', '7v6 + 2 GKs', 15, 15, 'Full pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 460),
  ('Crossing runs in a two-zone 6v6', 'finishing', 'opposed', 'in_possession', 139, 139, NULL, NULL, 'Organised, coordinated runs into key areas of the box from crosses and set pieces.', 'Half pitch split into 2 halves with full goals and keepers at each end; 6v6 outfield, one player per team starting in zone 2 and the rest in zone 1.', 'Each rep starts with an orange cross from the side; before it orange make set runs: near post, far post, penalty spot, and one holding at the edge of the box. Blues defend and if they clear they counter to the other goal. Restart with a cross after every goal or ball out.', 'Headed goal counts double.', NULL, 'Quality delivery and well-timed runs.', '6v6 + 2 GKs', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 470),
  ('8v8 corner-zone wing game', 'small_sided_game', 'opposed', 'in_possession', 140, 140, NULL, NULL, 'Creating scoring chances through the flank.', 'Half pitch with 4 corner zones, a winger in each; 5v5 in the main area plus keepers in full goals at both ends.', 'Keeper plays into the main area; the four work it wide to a winger who receives in his corner zone and crosses while teammates attack the box. Defending team win it and go to their own wingers.', 'Only wingers may enter corner zones until the ball is played in. Normal goal = 1, goal from a winger''s cross = 2.', 'Remove the keepers to make finishing easier.', 'Find the free man; if it is crowded switch play quickly.', '8v8 incl. GKs (5v5 + 4 wingers)', 16, 16, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 480),
  ('8v8 flank game with free first touch', 'small_sided_game', 'opposed', 'in_possession', 141, 141, NULL, NULL, 'Building play and creating chances from the wings.', 'Area 10 yards longer than half a pitch, full goals with keepers; both teams 3-2-2 (CB, two full backs, two CMs, two wingers); attacking team''s wingers start in the side zones.', 'Keeper starts, wingers step into the side zones, team builds and passes to a winger. After his free first touch the defender can engage. Winger either beats the man outside and crosses, or fakes to feet and spins in behind. Defenders win it and counter. Restart from the other team''s keeper.', 'Winger''s first touch in the zone is free. Headed goal counts double.', NULL, 'Wingers move away before showing (forward then back, or back then in behind); do not make the ball in behind predictable.', '8v8 incl. GKs', 16, 16, 'Half pitch + 10 yards', NULL, NULL, NULL, true, true, true, 'U14-U15', 490),
  ('Midfield-attack combinations 6v4 (+GK)', 'phase_of_play', 'overload', 'in_possession', 142, 142, NULL, NULL, 'Combination play between midfielders and forwards to exploit overloads.', 'Half pitch with full goal and keeper and two small goals on halfway; 2v1 in midfield, wingers 1v1 v full backs, striker and No.10 2v1 against a centre back.', 'Orange midfielders pass into the 9 or 10, who shows to feet; the other forward then attacks the space, with midfielders and wingers supporting (e.g. 10 lays into a running 8 while the 9 runs behind). Blues defend and score in the small goals.', 'Winning moment: 3 sequences, first team to 3 goals wins each.', 'Add a second centre back so the forwards face 2v2 and midfield support matters more.', 'Forwards read the defender to choose; play the final ball early into space to use the overload.', '6v4 + GK', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 500),
  ('Switching play pattern in a 6v5 (+GK)', 'combination', 'passive', 'in_possession', 143, 143, NULL, NULL, 'Coordinated movement and positional play to switch and attack the box.', 'Two zones: orange CB 5 and CM 8 in the small zone, 10, 7, 11 and 9 in the main zone; full goal with keeper, 5 blue defenders in a 3-2, two small goals on the zone line.', 'Set sequence: 5 to 11 who checks back, to 8, to 9; 9 drops and plays first time to 8; 10 runs beyond; 8 switches to 7 who beats his man and crosses; 9 front post, 10 penalty spot, 11 back post, 8 edge of box. Start unopposed or passive, then live (defenders active once their man has passed).', 'Defenders score in the small goals. All reset after a goal except 5 and 8 who swap. After 8 reps start from the other side.', 'Add or remove defenders to suit the forwards.', NULL, '6v5 + GK', 12, 12, NULL, NULL, NULL, NULL, true, true, true, 'U14-U15', 510),
  ('Striker drops into free zone 6v5 (+GK)', 'phase_of_play', 'overload', 'in_possession', 144, 144, NULL, NULL, 'Passing into a dropping striker and linking midfield with the forwards.', 'Half pitch: 10 x 10 yard free zone ahead of the box; orange 6, 8, 10, 7, 11, 9 v blue two CMs, two full backs, one CB; full goal + keeper, two small goals on halfway.', 'Orange midfielders move it, looking for the 9 to drop out of the free zone to receive; the blue CB cannot leave the zone before him. Once the 9 has it the zone no longer applies and orange attack. Blues win it and score in a small goal.', 'CB tied to the free zone until the striker drops out. Striker''s goals count double.', 'Coach can resize the free zone to suit the striker.', 'Keep eye contact with the passer; time the drop.', '6v5 + GK', 12, 12, 'Half pitch; free zone 10 x 10 yards', NULL, NULL, NULL, true, true, true, 'U14-U15', 520),
  ('Forward play 7v7 (+GK): 9 and 10 switch', 'phase_of_play', 'opposed', 'in_possession', 145, 145, NULL, NULL, 'Short and long coordinated movement of the 9 and 10 to create space and keep the ball.', 'Half pitch, full goal and keeper at one end, two cone gates on halfway; coaches with balls on each side; orange 1-3-3 v blue 4-3-3 shape.', 'Coach feeds orange. 9 drops and plays first time back into midfield; 10 runs forward into the 9''s spot; ball switched, then 10 drops back to receive; once the 10 has touched it orange may score. Blues win it and dribble through a cone gate. Restart from the other side.', 'Both 9 and 10 must touch the ball before a goal counts. Winning moment: 10 reps alternating coaches, most goals wins.', NULL, 'Move into the space your dropping teammate leaves; read the new picture quickly.', '7v7 + GK + 2 coaches', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 530),
  ('Build up then attack space 7v6 (+GK)', 'phase_of_play', 'overload', 'in_possession', 146, 146, NULL, NULL, 'Keeping possession, building up and exploiting space in the opposition half.', 'Full pitch up to the edge of the box; full goal with keeper at one end, two small goals at the other; a middle zone between box and halfway where all outfielders start; orange CB, 3 CMs, 2 wingers, striker v blue 3-3.', 'Orange keep the ball in the zone, then play into space in the opposition half; restrictions drop and it becomes 7v6 to goal. Blues win it and score in a small goal; their keeper sweeps long balls.', 'All orange players must be past halfway for a goal to count. Goal after a long pass counts double.', NULL, 'Be patient keeping it in a tight space; play forward when there is space and a good run.', '7v6 + GK', 14, 14, 'Full pitch to penalty area', NULL, NULL, NULL, true, true, true, 'U14-U15', 540),
  ('8v8 through balls into an end zone', 'small_sided_game', 'opposed', 'in_possession', 147, 147, NULL, NULL, 'Passing in behind the back line and timing the run.', '10 yards longer than half a pitch with full goals and keepers; end zone level with the penalty area; orange 3-1-3, blue back 4 and 3 CMs.', 'Orange keeper starts; team builds and slips a through ball for a runner into the end zone, after which all may move and support (e.g. 7 runs onto 8''s pass and crosses for 11). Blues defend and counter at the other goal.', 'Blues may enter the end zone only after the ball is played in. Striker''s goals count double.', NULL, 'Quick circulation and combinations to free the 9; on winning it, play forward behind the line at once.', '8v8 incl. GKs', 16, 16, 'Half pitch + 10 yards', NULL, NULL, NULL, true, true, true, 'U14-U15', 550),
  ('Front four press in a dynamic game', 'defending', 'opposed', 'out_of_possession', 158, 159, NULL, NULL, 'Collective pressing by the front four to stop the opponent playing out.', 'Two small goals at one end, half the centre circle as a target zone at the other; orange 9, 7, 11, 10 v blue back 4, CM 6 and striker 9 who stays in the circle; coach serves.', 'Coach passes to blue who build with a 5v4 edge. Orange press together, block passes into the blue 9, win it and score in a small goal. Ball out = coach restarts to a blue CB.', 'Blue score 1 by reaching their 9 in the circle or making 10 straight passes; only the blue 9 may enter the circle.', 'Two-zone game with big goals and keepers: 5 (+GK) blues v 4 orange in zone 1, dribble or pass to the striker to get into zone 2 and score.', '9: run between the CBs to cut the square pass, force it wide, do not get dribbled. Left winger: let the right back open, tuck in diagonally, block the long ball, press when he receives. Right winger: tuck in as the 9 presses, cover 9 or 10. 10: stand next to or ahead of his man, leave him to cut the ball to the striker, coach the front three.', '4v6 + coach', 11, 11, NULL, NULL, NULL, NULL, true, false, true, 'U14-U15', 560),
  ('High press 6v5 (+GK) SSG', 'defending', 'opposed', 'out_of_possession', 160, 160, NULL, NULL, 'Disrupting the opponent''s build-up and winning the ball high.', 'Half pitch with a line marking a high pressing zone; blue GK, back 4 and CM 6 v orange 6, 8, 10, 7, 11, 9; full goal with keeper, small/empty goal at the other end.', 'Blue keeper starts; blues try to play through the press and score in the empty goal. Orange press in the opposition half, win it and score past the keeper.', 'First to 6 goals wins. Orange goal after winning the ball in the high zone counts double.', NULL, 'Curved runs to steer play; show the opponent inside so others can push up; do not dive in; pressure the ball and mark the next receivers.', '6v5 + GK', 12, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U14-U15', 570),
  ('High press 8v8 between the boxes', 'defending', 'opposed', 'out_of_possession', 161, 161, NULL, NULL, 'Pressing high to block the opponent''s build-up.', 'Area between the two penalty areas with full goals and keepers; orange 3-1-3, blue 4-3; halfway line marked.', 'Blue keeper starts and blues build to score. Orange press high in the blue half, block forward passes, force play inside and intercept before scoring. Blues aim to break the press and use the space left behind.', 'Team in possession limited to 2 touches in its own half. Orange goal after a win in the blue half counts double.', NULL, NULL, '8v8 incl. GKs', 16, 16, 'Between the penalty areas', NULL, NULL, NULL, true, true, true, 'U14-U15', 580),
  ('Three-zone cover and take over marking', 'defending', 'opposed', 'out_of_possession', 162, 162, NULL, NULL, 'Taking over marking and covering while pressing in midfield.', 'Pitch split into 3 zones: each team has a CB in its end zone and 3 CMs in the middle zone; coach with balls at the side.', 'Coach passes to a CB; an opposing CM (e.g. No.10) steps up to close him, leaving a midfielder free, so the other CB steps into midfield to mark him. After that all zones open. Blues try to play through and dribble over the end line; orange win it and do the same.', 'Dribble over the end line = 1 point. Restart with the coach''s pass to a CB.', NULL, 'Close in once the opponent receives; coach the player in front of you to manage the takeover.', '4v4 + coach', 8, 8, NULL, NULL, NULL, NULL, false, false, true, 'U14-U15', 590),
  ('Back four shift and stay compact 4 (+GK) v 5', 'defending', 'opposed', 'out_of_possession', 163, 164, NULL, NULL, 'Back line moving as a unit to keep distances and prevent dangerous 1v1s.', 'Area with 4 orange defenders and a keeper v blue CMs 8 and 10, two wingers and a striker; end line in front of the goal.', 'Blue 8 starts with a pass; blues move it fast, get wide and dribble over the end line, then try to score past the keeper. Orange CB 5 steps out to mark blue 10; the other three shift together, keep a line and force play inside. If orange win it they dribble over the opposite line.', 'Blue 8 cannot dribble over the line or score and has 2 touches. Line = 1, goal = extra 1.', NULL, 'Move with the ball; near full back closes the winger, others shift; take away the winger''s speed; coach the one stepping out; open body to see ball and man; judge how far to shift; decide whether to duel the striker or hold.', '4 + GK v 5', 10, 10, NULL, NULL, NULL, NULL, true, true, true, 'U14-U15', 600),
  ('Press and shift cover in a 5v6 SSG', 'defending', 'opposed', 'out_of_possession', 165, 166, NULL, NULL, 'Defenders reacting quickly to shift and cover when the ball is far side or play goes through the centre.', 'Narrowed half pitch with full goals and keepers; orange CBs 4 and 5, full backs 2 and 3 v blue 2-3 (two CMs on 2 touches, wingers 7 and 11, striker 9).', 'Blue keeper plays to a CM; orange 5 steps up to press and show play one way; blues build fast to get wide or through the middle and score. Orange back three keep a line, shift across, force play inside, win it and counter to the other goal.', 'Blue central midfielders limited to 2 touches.', 'Start 4v5 and add players.', 'Far full back shifts in to cover the CB; set how far full backs tuck in; take over the striker when a CB steps out; keeper organises and sweeps; counter quickly after winning it.', '5v6 incl. GKs', 13, 13, 'Half pitch, narrowed', NULL, NULL, NULL, true, true, true, 'U14-U15', 610)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'dutch-academy-football-coaching-u14-15-functional-training-tactical-practices-fr') b;
INSERT INTO schema_migrations (filename) VALUES ('2408-exercises-book-dutch-academy-football-coaching-u14-15-functional-training-t.sql') ON CONFLICT DO NOTHING;
